$passed=0;
function eq(mixed $a,mixed $b):void{if($a!==$b)throw new \RuntimeException(var_export($a,true).' !== '.var_export($b,true));}
function test(string $name,callable $fn):void{global $passed;$fn();$passed++;echo "PASS $name\n";}
function rejects(callable $fn,string $key):void{try{$fn();}catch(Problem $e){eq($e->key,$key);return;}throw new \RuntimeException('Expected '.$key);}
function account(string $role='customer'):array{$id=id();$user=['id'=>$id,'name'=>'Admin QA','email'=>$id.'@example.invalid','role'=>$role,'status'=>'active'];query('INSERT INTO users (id,name,email,password_hash,referral_code,role,created_at) VALUES (?,?,?,?,?,?,?)',[$id,$user['name'],$user['email'],'never-return-this-hash',id(),$role,now()]);query('INSERT INTO wallets (user_id,balance_cents) VALUES (?,?)',[$id,2000]);return $user;}
$a=account('admin');$u=account();
function act(string $section,string $action,string $id,array $extra=[]):array{global $a;return Admin::action($a,['section'=>$section,'action'=>$action,'id'=>$id,'reason'=>'Support test']+$extra);}
$inbox=id();query('INSERT INTO inboxes (id,user_id,address,provider_id,status,price_cents,expires_at,created_at) VALUES (?,?,?,?,?,?,?,?)',[$inbox,$u['id'],'qa@example.invalid','mailbox-test','active',70,'2099-01-01 00:00:00',now()]);
$ad=id();query('INSERT INTO ads (id,user_id,title,target_url,banner_file,banner_mime,request_hash,idempotency_key,price_cents,status,created_at,expires_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',[$ad,$u['id'],'Original ad','https://example.com','qa.png','image/png','hash',id(),1000,'active',now(),'2099-01-01 00:00:00']);
$order=id();query('INSERT INTO orders (id,user_id,provider,product,service,status,price_cents,price_tier,idempotency_key,request_hash,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',[$order,$u['id'],'textverified','usa','google','pending',320,'retail',id(),'hash',now(),now()]);
$smm=id();query('INSERT INTO smm_orders (id,user_id,service,service_name,target,quantity,price_cents,status,created_at) VALUES (?,?,?,?,?,?,?,?,?)',[$smm,$u['id'],'101','Instagram Likes','https://example.com/profile',100,100,'completed',now()]);
$payment=id();query('INSERT INTO payments (id,user_id,provider,amount_cents,currency,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)',[$payment,$u['id'],'stripe',1000,'USD','successful',now(),now()]);
