$tempOperation=id();query('INSERT INTO temp_mail_operations (id,user_id,idempotency_key,operation,request_hash,price_cents,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?)',[$tempOperation,$u['id'],id(),'create','hash',70,'pending',now(),now()]);

test('Every admin service method rejects ordinary and disabled accounts',function()use($u,$a){foreach([$u,array_replace($a,['status'=>'disabled'])]as$actor){rejects(fn()=>Admin::overview($actor),'FORBIDDEN');rejects(fn()=>Admin::listing($actor,'users',[]),'FORBIDDEN');rejects(fn()=>Admin::record($actor,'users',$u['id']),'FORBIDDEN');rejects(fn()=>Admin::action($actor,[]),'FORBIDDEN');rejects(fn()=>Admin::settings($actor),'FORBIDDEN');rejects(fn()=>Admin::saveSettings($actor,[]),'FORBIDDEN');}});
test('Lists all implemented features without hashes or secret payloads',function()use($a){foreach(['users','numbers','boost-orders','temp-mail','ads','wallet-history','payments','support','operations','audit-log']as$section){$list=Admin::listing($a,$section,[]);eq($list['per_page'],20);eq(str_contains(json_encode($list),'password_hash'),false);eq(str_contains(json_encode($list),'request_hash'),false);}});
test('Admin lists support search status and customer filters with safe section whitelist',function()use($a,$u){eq(Admin::listing($a,'users',['search'=>$u['email']])['total'],1);eq(Admin::listing($a,'ads',['user_id'=>$u['id'],'status'=>'active'])['total'],1);eq(Admin::listing($a,'ads',['user_id'=>'missing'])['total'],0);rejects(fn()=>Admin::listing($a,'users; DROP TABLE users',[]),'NOT_FOUND');});
test('Customer detail includes wallet and services but never credentials',function()use($a,$u){$r=Admin::record($a,'users',$u['id']);eq($r['wallet']['balance_usd'],'20.00');eq($r['counts']['orders'],1);eq(isset($r['record']['password_hash']),false);rejects(fn()=>Admin::record($a,'users','missing'),'NOT_FOUND');});
test('Wallet adjustment is exactly once on retry and conflicts on altered inputs',function()use($u){$extra=['amount_usd'=>'5.00','direction'=>'credit','idempotency_key'=>'stable-key'];act('users','adjust-wallet',$u['id'],$extra);act('users','adjust-wallet',$u['id'],$extra);eq(Wallet::balance($u['id'])['balance_usd'],'25.00');rejects(fn()=>act('users','adjust-wallet',$u['id'],array_replace($extra,['amount_usd'=>'6.00'])),'IDEMPOTENCY_CONFLICT');});
test('Wallet debits respect available balance and validate direction and amount',function()use($u){rejects(fn()=>act('users','adjust-wallet',$u['id'],['amount_usd'=>'100.00','direction'=>'debit','idempotency_key'=>'debit']),'INSUFFICIENT_FUNDS');rejects(fn()=>act('users','adjust-wallet',$u['id'],['amount_usd'=>'0.00','direction'=>'credit','idempotency_key'=>'zero']),'INVALID_AMOUNT');rejects(fn()=>act('users','adjust-wallet',$u['id'],['amount_usd'=>'5.00','direction'=>'invalid','idempotency_key'=>'bad']),'INVALID_AMOUNT');});
test('Account changes revoke sessions and prevent administrator self lockout',function()use($a,$u){query('INSERT INTO sessions (token_hash,user_id,expires_at) VALUES (?,?,?)',['qa-token',$u['id'],'2099-01-01 00:00:00']);act('users','update',$u['id'],['status'=>'disabled','role'=>'customer']);eq(one('SELECT status FROM users WHERE id=?',[$u['id']])['status'],'disabled');eq(one('SELECT COUNT(*) n FROM sessions WHERE user_id=?',[$u['id']])['n'],0);rejects(fn()=>act('users','update',$a['id'],['role'=>'customer']),'SELF_LOCKOUT');act('users','update',$u['id'],['status'=>'active','role'=>'customer']);});
test('Ad moderation edits validated fields and removes without refund',function()use($a,$u,$ad){$before=Wallet::balance($u['id']);act('ads','edit',$ad,['title'=>'Updated ad','target_url'=>'https://example.org']);eq(Admin::record($a,'ads',$ad)['record']['title'],'Updated ad');rejects(fn()=>act('ads','edit',$ad,['title'=>'Bad','target_url'=>'javascript:alert(1)']),'INVALID_TARGET');act('ads','remove',$ad);eq(one('SELECT status FROM ads WHERE id=?',[$ad])['status'],'removed');eq(Wallet::balance($u['id']),$before);});
test('Inbox support extension and deletion preserve existing charge',function()use($inbox,$u){act('temp-mail','extend',$inbox);$r=one('SELECT * FROM inboxes WHERE id=?',[$inbox]);eq($r['expires_at'],'2099-01-02 00:00:00');eq((int)$r['price_cents'],70);$balance=Wallet::balance($u['id']);act('temp-mail','delete',$inbox);eq(one('SELECT status FROM inboxes WHERE id=?',[$inbox])['status'],'deleted');eq(Wallet::balance($u['id']),$balance);rejects(fn()=>act('temp-mail','extend',$inbox),'INBOX_EXPIRED');});
test('Expired active records appear under expired filters',function()use($a,$inbox){query("UPDATE inboxes SET status='active',expires_at='2000-01-01 00:00:00' WHERE id=?",[$inbox]);eq(Admin::listing($a,'temp-mail',['status'=>'expired'])['items'][0]['status'],'expired');eq(Admin::listing($a,'temp-mail',['status'=>'active'])['total'],0);});
test('Support statuses are managed and successful payments verify without duplicate credit',function()use($support,$payment,$u){act('support','update',$support,['status'=>'resolved']);eq(one('SELECT status FROM support_tickets WHERE id=?',[$support])['status'],'resolved');$balance=Wallet::balance($u['id']);act('payments','verify',$payment);eq(Wallet::balance($u['id']),$balance);});
test('Pending operations include number and temporary email recovery records',function()use($a,$order,$tempOperation){$list=Admin::listing($a,'operations',[]);eq($list['total'],2);eq(Admin::record($a,'operations',$order)['record']['product'],'usa');eq(Admin::record($a,'operations',$tempOperation)['record']['product'],'temp-mail');});
