$settings=['number_fx'=>'1','number_margin_usd'=>'0.70','smm_fx'=>'0.0004','smm_markup'=>'100','temp_mail_price_usd'=>'0.80','ads_price_usd'=>'12.00','reason'=>'Approved pricing test'];
test('Pricing controls apply server-side FX margins and future email and ad charges',function()use($a,$settings){Admin::saveSettings($a,$settings);eq(TempMail::price(),80);eq(Ads::price(),1200);eq(Pricing::numberQuote(250,'textverified',Pricing::setting('textverified_pricing')),320);eq(Pricing::quote(250000,Pricing::setting('smm_pricing'),'retail',true),200);$r=Admin::settings($a);eq($r['smm_fx'],'0.00040000');eq($r['ads_price_usd'],'12.00');eq(is_bool($r['connections']['numbers']),true);});
