test('Overview includes cross-feature counts and financial figures with an audit trail',function()use($a){$o=Admin::overview($a);eq($o['users'],2);eq($o['numbers'],1);eq($o['boost_orders'],1);eq($o['pending_operations'],2);eq($o['credited_topups_cents'],1000);eq(count($o['recent_activity'])>0,true);eq(Admin::listing($a,'audit-log',['search'=>'admin_wallet_adjusted'])['total'],1);});
test('Wallet filters use exact kind direction numeric sort and London date boundaries',function()use($a,$u){
 tx(function()use($u){Wallet::change($u['id'],'refund',10,'filter-credit','filter credit');Wallet::change($u['id'],'purchase',-3,'filter-debit','filter debit');});
 query("UPDATE ledger SET created_at='2026-10-24 23:00:00' WHERE reference='filter-credit'");
 query("UPDATE ledger SET created_at='2026-10-26 00:00:00' WHERE reference='filter-debit'");
 $r=Admin::listing($a,'wallet-history',['kind'=>'refund','direction'=>'credit','from'=>'2026-10-25','until'=>'2026-10-25']);eq($r['total'],1);eq($r['items'][0]['reference'],'filter-credit');
 $r=Admin::listing($a,'wallet-history',['sort'=>'amount_cents','order'=>'asc']);$amounts=array_map(fn($r)=>(int)$r['amount_cents'],$r['items']);$sorted=$amounts;sort($sorted);eq($amounts,$sorted);
 eq(in_array('refund',$r['filter_options']['kind'],true),true);
 rejects(fn()=>Admin::listing($a,'users',['sort'=>'password_hash']),'INVALID_SORT');rejects(fn()=>Admin::listing($a,'users',['order'=>'desc;drop table users']),'INVALID_SORT');rejects(fn()=>Admin::listing($a,'users',['from'=>'2026-02-30']),'INVALID_DATE');rejects(fn()=>Admin::listing($a,'users',['from'=>'2026-10-25','until'=>'2026-10-24']),'INVALID_DATE');
});
test('Account editing validates email and password and supports role filtering',function()use($a,$u){
 act('users','update',$u['id'],['name'=>'Edited customer','email'=>'edited@example.invalid','password'=>'QA-new-password-2026']);$r=one('SELECT * FROM users WHERE id=?',[$u['id']]);eq($r['name'],'Edited customer');eq(password_verify('QA-new-password-2026',$r['password_hash']),true);
 rejects(fn()=>act('users','update',$u['id'],['email'=>$a['email']]),'ACCOUNT_EXISTS');rejects(fn()=>act('users','update',$u['id'],['password'=>'short']),'WEAK_PASSWORD');
