});
test('Locked customers cannot reserve spend or renew but existing settlement and refunds remain possible',function()use($u){
 tx(fn()=>Wallet::change($u['id'],'reservation',0,'lock-before','existing reservation',20));
 act('users','update',$u['id'],['status'=>'disabled']);
 rejects(fn()=>tx(fn()=>Wallet::change($u['id'],'reservation',0,'lock-reserve','new reservation',10)),'FORBIDDEN');rejects(fn()=>tx(fn()=>Wallet::change($u['id'],'purchase',-10,'lock-buy','new purchase')),'FORBIDDEN');rejects(fn()=>tx(fn()=>Wallet::change($u['id'],'renewal',-10,'lock-renew','new renewal')),'FORBIDDEN');
 tx(fn()=>Wallet::change($u['id'],'purchase',-20,'lock-capture','settle existing',-20));tx(fn()=>Wallet::change($u['id'],'refund',20,'lock-refund','confirmed refund'));act('users','update',$u['id'],['status'=>'active']);
});
test('Numeric administrator IDs are unique stable and accepted by customer filters',function()use($a,$u){
 $record=Admin::record($a,'users',$u['id']);$number=$record['display_ids'][$u['id']];eq(is_int($number),true);eq($number>0,true);eq(Admin::record($a,'users',$u['id'])['display_ids'][$u['id']],$number);
 eq(Admin::listing($a,'wallet-history',['user_id'=>(string)$number])['total']>0,true);
