test('Rental management isolates service records and treats elapsed rentals as expired',function()use($a,$u,$order){
 $r=id();query('INSERT INTO orders (id,user_id,provider,provider_order_id,product,service,phone,status,price_cents,price_tier,idempotency_key,request_hash,created_at,updated_at,expires_at,rental_duration,rental_refundable) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$r,$u['id'],'textverified','qa-rental','long-term','google','12025550124','active',340,'retail',id(),'hash',now(),now(),'2000-01-01 00:00:00','sevenDay',1]);
 eq(Admin::listing($a,'rentals',['status'=>'active'])['total'],0);
 $expired=Admin::listing($a,'rentals',['status'=>'expired']);eq($expired['total'],1);eq($expired['items'][0]['status'],'expired');
 $detail=Admin::record($a,'rentals',$r);eq($detail['record']['status'],'expired');eq((int)$detail['record']['rental_refundable'],0);eq($detail['operations'],[]);
 rejects(fn()=>Admin::record($a,'rentals',$order),'NOT_FOUND');rejects(fn()=>Admin::record($a,'numbers',$r),'NOT_FOUND');
 rejects(fn()=>act('rentals','messages',$order),'NOT_FOUND');rejects(fn()=>act('rentals','sync',$order),'NOT_FOUND');
 rejects(fn()=>Admin::listing($u,'rentals',[]),'FORBIDDEN');
 $intent=id();query('INSERT INTO fulfilment_intents (id,user_id,product,operation,resource_id,request_hash,idempotency_key,price_cents,status,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)',[$intent,$u['id'],'long-term','renewal',$r,'private-hash',id(),340,'reconciliation',now(),now()]);
 $detail=Admin::record($a,'rentals',$r);eq($detail['operations'][0]['id'],$intent);eq($detail['operations'][0]['status'],'reconciliation');eq(isset($detail['operations'][0]['request_hash']),false);eq(is_int($detail['display_ids'][$intent]),true);
});
